style.css:
@-moz-document url-prefix("chrome://newtab/"), url-prefix("https://www.google.com") {
body {
    background: linear-gradient(to bottom, #cbe9ff 0%, #a0d7ff 100%);
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Anime_girl_smiling_wallpaper.webp/1920px-Anime_girl_smiling_wallpaper.webp.jpg");
    background-repeat: no-repeat;
    background-position: right bottom;
    background-size: contain;
    font-family: 'Segoe UI', sans-serif;
    color: #003366;
  }

  input[type="text"], input[type="search"] {
    background-color: rgba(255, 255, 255, 0.8) !important;
    border: 1px solid #a5d3f3 !important;
    border-radius: 10px !important;
    padding: 10px !important;
    box-shadow: 0 0 10px #a0d7ff !important;
  }

  .logo, .gb_He, .gb_zf, .gb_qe {
    filter: drop-shadow(0 0 4px #ffffffaa);
  }

  a, button {
    color: #004488 !important;
    text-shadow: 0 0 2px #fff;
  }

  .gb_Nd, .gb_Bd {
    background-color: rgba(255, 255, 255, 0.6) !important;
    border-radius: 12px !important;
    backdrop-filter: blur(10px);
    box-shadow: 0 0 8px #ffffff66;
  }
}
